1	(function () {
2	  window.ZIMM_RENDERERS = window.ZIMM_RENDERERS || {};
3	  var bool = window.ZIMM.bool;
4	
5	  window.ZIMM_RENDERERS['zimm-navigation'] = function (el, slots) {
6	    var initialActive = bool(el, 'active');
7	
8	    // ---- State: closure-local, mirrors the old Shadow-DOM component's
9	    // instance fields (_activeIndex / _mobileView / _prevMobileView). Render
10	    // functions run once with no live reactivity (see authoring.md "No live
11	    // reactivity"), so this whole interaction/state-machine is wired here in
12	    // the render function's OWN body via a single click listener attached
13	    // directly to `el`, not inside the returned markup string -- this is the
14	    // "listen across the whole rendered subtree" mechanism from
15	    // authoring.md's "The render function". Any DOM these functions query
16	    // via el.querySelector(...) is guaranteed to exist by the time they
17	    // actually run, because they only ever run later, from the click
18	    // handler, by which point the runtime has already set el.innerHTML to
19	    // this function's returned string. ----
20	    var activeIndex = -1;
21	    var mobileView = null; // null | 'home' | 0-4
22	    var prevMobileView = null;
23	
24	    function isMobile() {
25	      return window.matchMedia('(max-width: 767px)').matches;
26	    }
27	
28	    function mobileCloseTransition(root) {
29	      if (!isMobile()) return;
30	      root.classList.add('zimm-navigation-mobile-closing');
31	      setTimeout(function () { root.classList.remove('zimm-navigation-mobile-closing'); }, 300);
32	    }
33	
34	    // Mega-menu panels are supplied by the consuming page as slotted
35	    // <zimm-mega-menu slot="menu-*"> children (contract: "menu-panel" slot,
36	    // "Not defined in this component, supplied by the consuming page").
37	    // captureSlots interpolates that consumer markup directly into this
38	    // component's returned HTML (no native <slot> any more), so by the time
39	    // any handler below runs, each panel-section's direct children are
40	    // whatever <zimm-mega-menu> tags the consumer supplied, already rendered
41	    // by the runtime's page walk. zimm-mega-menu's own renderer replaces its
42	    // wrapper tag's content with a real `.zimm-mega-menu` root div and the
43	    // wrapper becomes an inert display:contents shell -- open/closing/mobile
44	    // must be set on that INNER div, never on the outer <zimm-mega-menu> tag
45	    // (see zimm-mega-menu.js's own comment on this).
46	    function innerMegaMenus(section) {
47	      var wrappers = section.querySelectorAll('zimm-mega-menu');
48	      var inner = [];
49	      for (var i = 0; i < wrappers.length; i++) {
50	        var m = wrappers[i].querySelector('.zimm-mega-menu');
51	        if (m) inner.push(m);
52	      }
53	      return inner;
54	    }
55	
56	    function syncNavItems(root, items) {
57	      var navItems = items || root.querySelectorAll('.zimm-navigation-nav-links .zimm-nav-item');
58	      Array.prototype.forEach.call(navItems, function (item, i) {
59	        if (i === activeIndex) {
60	          item.classList.add('zimm-nav-item-active');
61	          item.setAttribute('aria-current', 'true');
62	        } else {
63	          item.classList.remove('zimm-nav-item-active');
64	          item.removeAttribute('aria-current');
65	        }
66	      });
67	    }
68	
69	    function syncPanelSection(root) {
70	      var sections = root.querySelectorAll('.zimm-navigation-panel-section');
71	      var isClosing = activeIndex === -1;
72	
73	      Array.prototype.forEach.call(sections, function (s, i) {
74	        var isActive = i === activeIndex;
75	        var wasActive = s.classList.contains('zimm-navigation-panel-section-active');
76	        var menus = innerMegaMenus(s);
77	
78	        if (isActive) {
79	          s.classList.add('zimm-navigation-panel-section-active');
80	          menus.forEach(function (m) {
81	            m.removeAttribute('closing');
82	            requestAnimationFrame(function () { m.setAttribute('open', ''); });
83	          });
84	        } else if (wasActive && isClosing) {
85	          menus.forEach(function (m) {
86	            m.removeAttribute('open');
87	            m.setAttribute('closing', '');
88	          });
89	          setTimeout(function () {
90	            s.classList.remove('zimm-navigation-panel-section-active');
91	            menus.forEach(function (m) { m.removeAttribute('closing'); });
92	          }, 300);
93	        } else {
94	          s.classList.remove('zimm-navigation-panel-section-active');
95	          menus.forEach(function (m) {
96	            m.removeAttribute('open');
97	            m.removeAttribute('closing');
98	          });
99	        }
100	      });
101	    }
102	
103	    function animateTransition(homeEl, subContent, panel, direction) {
104	      var dur = '300ms var(--zimm-motion-easing-slides)';
105	
106	      homeEl.style.animation = '';
107	      subContent.style.animation = '';
108	
109	      if (direction === 'forward') {
110	        // Button crossfade: X fades out, chevron fades in
111	        panel.classList.add('zimm-navigation-menu-panel-mobile-sub');
112	        homeEl.style.display = 'flex';
113	        subContent.style.display = 'flex';
114	        homeEl.style.animation = 'zimm-navigation-slide-out-left ' + dur + ' both';
115	        subContent.style.animation = 'zimm-navigation-slide-in-right ' + dur + ' both';
116	
117	        homeEl.addEventListener('animationend', function () {
118	          homeEl.style.display = 'none';
119	          homeEl.style.animation = '';
120	          subContent.style.animation = '';
121	        }, { once: true });
122	
123	      } else {
124	        // Button crossfade: chevron fades out, X fades in (immediate, before slide completes)
125	        panel.classList.remove('zimm-navigation-menu-panel-mobile-sub');
126	        homeEl.style.display = 'flex';
127	        homeEl.style.animation = 'zimm-navigation-slide-in-left ' + dur + ' both';
128	        subContent.style.animation = 'zimm-navigation-slide-out-right ' + dur + ' both';
129	
130	        subContent.addEventListener('animationend', function () {
131	          subContent.style.display = 'none';
132	          homeEl.style.animation = '';
133	          subContent.style.animation = '';
134	        }, { once: true });
135	      }
136	    }
137	
138	    function syncMobileView(root) {
139	      var panel = root.querySelector('.zimm-navigation-menu-panel');
140	      var homeEl = root.querySelector('.zimm-navigation-mobile-home');
141	      var subContent = root.querySelector('.zimm-navigation-mobile-sub-content');
142	      var sections = root.querySelectorAll('.zimm-navigation-panel-section');
143	
144	      if (!panel) return;
145	
146	      var prev = prevMobileView;
147	      prevMobileView = mobileView;
148	
149	      if (!isMobile() || mobileView === null) {
150	        panel.classList.remove('zimm-navigation-menu-panel-mobile-sub');
151	        if (homeEl) homeEl.style.cssText = '';
152	        if (subContent) subContent.style.cssText = '';
153	        Array.prototype.forEach.call(sections, function (s) {
154	          s.classList.remove('zimm-navigation-panel-section-active');
155	          innerMegaMenus(s).forEach(function (m) {
156	            m.removeAttribute('mobile');
157	            m.removeAttribute('open');
158	            m.removeAttribute('closing');
159	          });
160	        });
161	        return;
162	      }
163	
164	      if (mobileView === 'home') {
165	        Array.prototype.forEach.call(sections, function (s) {
166	          s.classList.remove('zimm-navigation-panel-section-active');
167	          innerMegaMenus(s).forEach(function (m) {
168	            m.removeAttribute('mobile');
169	            m.removeAttribute('open');
170	            m.removeAttribute('closing');
171	          });
172	        });
173	
174	        if (prev !== null && prev !== 'home') {
175	          animateTransition(homeEl, subContent, panel, 'back');
176	        } else {
177	          panel.classList.remove('zimm-navigation-menu-panel-mobile-sub');
178	          homeEl.style.display = 'flex';
179	          subContent.style.display = 'none';
180	          homeEl.style.animation = '';
181	        }
182	
183	      } else {
184	        var idx = mobileView;
185	        Array.prototype.forEach.call(sections, function (s, i) {
186	          var menus = innerMegaMenus(s);
187	          if (i === idx) {
188	            s.classList.add('zimm-navigation-panel-section-active');
189	            menus.forEach(function (m) {
190	              m.removeAttribute('open');
191	              m.removeAttribute('closing');
192	              m.setAttribute('mobile', '');
193	            });
194	          } else {
195	            s.classList.remove('zimm-navigation-panel-section-active');
196	            menus.forEach(function (m) {
197	              m.removeAttribute('mobile');
198	              m.removeAttribute('open');
199	              m.removeAttribute('closing');
200	            });
201	          }
202	        });
203	
204	        if (prev === 'home' || prev === null) {
205	          animateTransition(homeEl, subContent, panel, 'forward');
206	        } else {
207	          panel.classList.add('zimm-navigation-menu-panel-mobile-sub');
208	          subContent.style.display = 'flex';
209	        }
210	      }
211	    }
212	
213	    function updateActiveState(root) {
214	      var active = root.classList.contains('zimm-navigation-active');
215	
216	      var btn = root.querySelector('.zimm-navigation-hamburger-btn');
217	      if (btn) {
218	        btn.setAttribute('aria-expanded', String(active));
219	        btn.setAttribute('aria-label', active ? 'Close menu' : 'Open menu');
220	      }
221	
222	      var panel = root.querySelector('.zimm-navigation-menu-panel');
223	      if (panel) {
224	        panel.setAttribute('aria-hidden', String(!active));
225	      }
226	    }
227	
228	    function handleClick(e) {
229	      var root = el.querySelector('.zimm-navigation');
230	      if (!root) return;
231	
232	      var inMobileClose  = e.target.closest('.zimm-navigation-mobile-close-btn');
233	      var inMobileBack   = e.target.closest('.zimm-navigation-mobile-back-btn');
234	      var inMobileNavBtn = e.target.closest('.zimm-navigation-mobile-nav-btn');
235	      var inHamburger    = e.target.closest('.zimm-navigation-hamburger-btn');
236	      var inNavLinks     = e.target.closest('.zimm-navigation-nav-links');
237	      var inClose        = e.target.closest('.zimm-navigation-right-active');
238	
239	      if (inMobileClose) {
240	        mobileCloseTransition(root);
241	        activeIndex = -1;
242	        mobileView = null;
243	        prevMobileView = null;
244	        root.classList.remove('zimm-navigation-active');
245	        syncMobileView(root);
246	        updateActiveState(root);
247	
248	      } else if (inMobileBack) {
249	        mobileView = 'home';
250	        syncMobileView(root);
251	
252	      } else if (inMobileNavBtn) {
253	        mobileView = parseInt(inMobileNavBtn.getAttribute('data-index'), 10);
254	        syncMobileView(root);
255	
256	      } else if (inHamburger) {
257	        var willBeActive = !root.classList.contains('zimm-navigation-active');
258	        root.classList.toggle('zimm-navigation-active');
259	        if (willBeActive) {
260	          if (isMobile()) {
261	            mobileView = 'home';
262	            syncMobileView(root);
263	          }
264	        } else {
265	          mobileCloseTransition(root);
266	          activeIndex = -1;
267	          mobileView = null;
268	          prevMobileView = null;
269	          syncNavItems(root);
270	          syncPanelSection(root);
271	          syncMobileView(root);
272	        }
273	        updateActiveState(root);
274	
275	      } else if (inNavLinks) {
276	        var navItem = e.target.closest('.zimm-navigation-nav-links .zimm-nav-item');
277	        if (!navItem) return;
278	        var items = root.querySelectorAll('.zimm-navigation-nav-links .zimm-nav-item');
279	        var idx = Array.prototype.indexOf.call(items, navItem);
280	        if (idx === activeIndex) {
281	          activeIndex = -1;
282	          root.classList.remove('zimm-navigation-active');
283	        } else {
284	          activeIndex = idx;
285	          root.classList.add('zimm-navigation-active');
286	        }
287	        syncNavItems(root, items);
288	        syncPanelSection(root);
289	        updateActiveState(root);
290	
291	      } else if (e.target.closest('.zimm-navigation-search-trigger')) {
292	        el.dispatchEvent(new CustomEvent('zimm-search-open', { bubbles: true }));
293	
294	      } else if (inClose) {
295	        activeIndex = -1;
296	        root.classList.remove('zimm-navigation-active');
297	        syncNavItems(root);
298	        syncPanelSection(root);
299	        updateActiveState(root);
300	      }
301	    }
302	
303	    el.addEventListener('click', handleClick);
