(function () {
  window.ZIMM_RENDERERS = window.ZIMM_RENDERERS || {};
  var bool = window.ZIMM.bool;

  window.ZIMM_RENDERERS['zimm-navigation'] = function (el, slots) {
    var initialActive = bool(el, 'active');

    // ---- State: closure-local, mirrors the old Shadow-DOM component's
    // instance fields (_activeIndex / _mobileView / _prevMobileView). Render
    // functions run once with no live reactivity (see authoring.md "No live
    // reactivity"), so this whole interaction/state-machine is wired here in
    // the render function's OWN body via a single click listener attached
    // directly to `el`, not inside the returned markup string -- this is the
    // "listen across the whole rendered subtree" mechanism from
    // authoring.md's "The render function". Any DOM these functions query
    // via el.querySelector(...) is guaranteed to exist by the time they
    // actually run, because they only ever run later, from the click
    // handler, by which point the runtime has already set el.innerHTML to
    // this function's returned string. ----
    var activeIndex = -1;
    var mobileView = null; // null | 'home' | 0-4
    var prevMobileView = null;

    function isMobile() {
      return window.matchMedia('(max-width: 767px)').matches;
    }

    function mobileCloseTransition(root) {
      if (!isMobile()) return;
      root.classList.add('zimm-navigation-mobile-closing');
      setTimeout(function () { root.classList.remove('zimm-navigation-mobile-closing'); }, 300);
    }

    // Mega-menu panels are supplied by the consuming page as slotted
    // <zimm-mega-menu slot="menu-*"> children (contract: "menu-panel" slot,
    // "Not defined in this component, supplied by the consuming page").
    // captureSlots interpolates that consumer markup directly into this
    // component's returned HTML (no native <slot> any more), so by the time
    // any handler below runs, each panel-section's direct children are
    // whatever <zimm-mega-menu> tags the consumer supplied, already rendered
    // by the runtime's page walk. zimm-mega-menu's own renderer replaces its
    // wrapper tag's content with a real `.zimm-mega-menu` root div and the
    // wrapper becomes an inert display:contents shell -- open/closing/mobile
    // must be set on that INNER div, never on the outer <zimm-mega-menu> tag
    // (see zimm-mega-menu.js's own comment on this).
    function innerMegaMenus(section) {
      var wrappers = section.querySelectorAll('zimm-mega-menu');
      var inner = [];
      for (var i = 0; i < wrappers.length; i++) {
        var m = wrappers[i].querySelector('.zimm-mega-menu');
        if (m) inner.push(m);
      }
      return inner;
    }

    function syncNavItems(root, items) {
      var navItems = items || root.querySelectorAll('.zimm-navigation-nav-links .zimm-nav-item');
      Array.prototype.forEach.call(navItems, function (item, i) {
        if (i === activeIndex) {
          item.classList.add('zimm-nav-item-active');
          item.setAttribute('aria-current', 'true');
        } else {
          item.classList.remove('zimm-nav-item-active');
          item.removeAttribute('aria-current');
        }
      });
    }

    function syncPanelSection(root) {
      var sections = root.querySelectorAll('.zimm-navigation-panel-section');
      var isClosing = activeIndex === -1;

      Array.prototype.forEach.call(sections, function (s, i) {
        var isActive = i === activeIndex;
        var wasActive = s.classList.contains('zimm-navigation-panel-section-active');
        var menus = innerMegaMenus(s);

        if (isActive) {
          s.classList.add('zimm-navigation-panel-section-active');
          menus.forEach(function (m) {
            m.removeAttribute('closing');
            requestAnimationFrame(function () { m.setAttribute('open', ''); });
          });
        } else if (wasActive && isClosing) {
          menus.forEach(function (m) {
            m.removeAttribute('open');
            m.setAttribute('closing', '');
          });
          setTimeout(function () {
            s.classList.remove('zimm-navigation-panel-section-active');
            menus.forEach(function (m) { m.removeAttribute('closing'); });
          }, 300);
        } else {
          s.classList.remove('zimm-navigation-panel-section-active');
          menus.forEach(function (m) {
            m.removeAttribute('open');
            m.removeAttribute('closing');
          });
        }
      });
    }

    function animateTransition(homeEl, subContent, panel, direction) {
      var dur = '300ms var(--zimm-motion-easing-slides)';

      homeEl.style.animation = '';
      subContent.style.animation = '';

      if (direction === 'forward') {
        // Button crossfade: X fades out, chevron fades in
        panel.classList.add('zimm-navigation-menu-panel-mobile-sub');
        homeEl.style.display = 'flex';
        subContent.style.display = 'flex';
        homeEl.style.animation = 'zimm-navigation-slide-out-left ' + dur + ' both';
        subContent.style.animation = 'zimm-navigation-slide-in-right ' + dur + ' both';

        homeEl.addEventListener('animationend', function () {
          homeEl.style.display = 'none';
          homeEl.style.animation = '';
          subContent.style.animation = '';
        }, { once: true });

      } else {
        // Button crossfade: chevron fades out, X fades in (immediate, before slide completes)
        panel.classList.remove('zimm-navigation-menu-panel-mobile-sub');
        homeEl.style.display = 'flex';
        homeEl.style.animation = 'zimm-navigation-slide-in-left ' + dur + ' both';
        subContent.style.animation = 'zimm-navigation-slide-out-right ' + dur + ' both';

        subContent.addEventListener('animationend', function () {
          subContent.style.display = 'none';
          homeEl.style.animation = '';
          subContent.style.animation = '';
        }, { once: true });
      }
    }

    function syncMobileView(root) {
      var panel = root.querySelector('.zimm-navigation-menu-panel');
      var homeEl = root.querySelector('.zimm-navigation-mobile-home');
      var subContent = root.querySelector('.zimm-navigation-mobile-sub-content');
      var sections = root.querySelectorAll('.zimm-navigation-panel-section');

      if (!panel) return;

      var prev = prevMobileView;
      prevMobileView = mobileView;

      if (!isMobile() || mobileView === null) {
        panel.classList.remove('zimm-navigation-menu-panel-mobile-sub');
        if (homeEl) homeEl.style.cssText = '';
        if (subContent) subContent.style.cssText = '';
        Array.prototype.forEach.call(sections, function (s) {
          s.classList.remove('zimm-navigation-panel-section-active');
          innerMegaMenus(s).forEach(function (m) {
            m.removeAttribute('mobile');
            m.removeAttribute('open');
            m.removeAttribute('closing');
          });
        });
        return;
      }

      if (mobileView === 'home') {
        Array.prototype.forEach.call(sections, function (s) {
          s.classList.remove('zimm-navigation-panel-section-active');
          innerMegaMenus(s).forEach(function (m) {
            m.removeAttribute('mobile');
            m.removeAttribute('open');
            m.removeAttribute('closing');
          });
        });

        if (prev !== null && prev !== 'home') {
          animateTransition(homeEl, subContent, panel, 'back');
        } else {
          panel.classList.remove('zimm-navigation-menu-panel-mobile-sub');
          homeEl.style.display = 'flex';
          subContent.style.display = 'none';
          homeEl.style.animation = '';
        }

      } else {
        var idx = mobileView;
        Array.prototype.forEach.call(sections, function (s, i) {
          var menus = innerMegaMenus(s);
          if (i === idx) {
            s.classList.add('zimm-navigation-panel-section-active');
            menus.forEach(function (m) {
              m.removeAttribute('open');
              m.removeAttribute('closing');
              m.setAttribute('mobile', '');
            });
          } else {
            s.classList.remove('zimm-navigation-panel-section-active');
            menus.forEach(function (m) {
              m.removeAttribute('mobile');
              m.removeAttribute('open');
              m.removeAttribute('closing');
            });
          }
        });

        if (prev === 'home' || prev === null) {
          animateTransition(homeEl, subContent, panel, 'forward');
        } else {
          panel.classList.add('zimm-navigation-menu-panel-mobile-sub');
          subContent.style.display = 'flex';
        }
      }
    }

    function updateActiveState(root) {
      var active = root.classList.contains('zimm-navigation-active');

      var btn = root.querySelector('.zimm-navigation-hamburger-btn');
      if (btn) {
        btn.setAttribute('aria-expanded', String(active));
        btn.setAttribute('aria-label', active ? 'Close menu' : 'Open menu');
      }

      var panel = root.querySelector('.zimm-navigation-menu-panel');
      if (panel) {
        panel.setAttribute('aria-hidden', String(!active));
      }
    }

    function handleClick(e) {
      var root = el.querySelector('.zimm-navigation');
      if (!root) return;

      var inMobileClose  = e.target.closest('.zimm-navigation-mobile-close-btn');
      var inMobileBack   = e.target.closest('.zimm-navigation-mobile-back-btn');
      var inMobileNavBtn = e.target.closest('.zimm-navigation-mobile-nav-btn');
      var inHamburger    = e.target.closest('.zimm-navigation-hamburger-btn');
      var inNavLinks     = e.target.closest('.zimm-navigation-nav-links');
      var inClose        = e.target.closest('.zimm-navigation-right-active');

      if (inMobileClose) {
        mobileCloseTransition(root);
        activeIndex = -1;
        mobileView = null;
        prevMobileView = null;
        root.classList.remove('zimm-navigation-active');
        syncMobileView(root);
        updateActiveState(root);

      } else if (inMobileBack) {
        mobileView = 'home';
        syncMobileView(root);

      } else if (inMobileNavBtn) {
        mobileView = parseInt(inMobileNavBtn.getAttribute('data-index'), 10);
        syncMobileView(root);

      } else if (inHamburger) {
        var willBeActive = !root.classList.contains('zimm-navigation-active');
        root.classList.toggle('zimm-navigation-active');
        if (willBeActive) {
          if (isMobile()) {
            mobileView = 'home';
            syncMobileView(root);
          }
        } else {
          mobileCloseTransition(root);
          activeIndex = -1;
          mobileView = null;
          prevMobileView = null;
          syncNavItems(root);
          syncPanelSection(root);
          syncMobileView(root);
        }
        updateActiveState(root);

      } else if (inNavLinks) {
        var navItem = e.target.closest('.zimm-navigation-nav-links .zimm-nav-item');
        if (!navItem) return;
        var items = root.querySelectorAll('.zimm-navigation-nav-links .zimm-nav-item');
        var idx = Array.prototype.indexOf.call(items, navItem);
        if (idx === activeIndex) {
          activeIndex = -1;
          root.classList.remove('zimm-navigation-active');
        } else {
          activeIndex = idx;
          root.classList.add('zimm-navigation-active');
        }
        syncNavItems(root, items);
        syncPanelSection(root);
        updateActiveState(root);

      } else if (e.target.closest('.zimm-navigation-search-trigger')) {
        el.dispatchEvent(new CustomEvent('zimm-search-open', { bubbles: true }));

      } else if (inClose) {
        activeIndex = -1;
        root.classList.remove('zimm-navigation-active');
        syncNavItems(root);
        syncPanelSection(root);
        updateActiveState(root);
      }
    }

    el.addEventListener('click', handleClick);

    var activeCls = initialActive ? ' zimm-navigation-active' : '';
    var hamburgerExpanded = initialActive ? 'true' : 'false';
    var hamburgerLabel = initialActive ? 'Close menu' : 'Open menu';
    var panelHidden = initialActive ? 'false' : 'true';

    return '<header class="zimm-navigation' + activeCls + '" role="banner">'

      + '<nav class="zimm-navigation-bar" aria-label="Main navigation">'

      +   '<button class="zimm-navigation-hamburger-btn" aria-expanded="' + hamburgerExpanded + '" aria-controls="menu-panel" aria-label="' + hamburgerLabel + '">'
      +     '<zimm-icon class="zimm-navigation-icon-menu" type="menu" size="20" aria-hidden="true"></zimm-icon>'
      +     '<zimm-icon class="zimm-navigation-icon-close-mobile" type="close" size="20" aria-hidden="true"></zimm-icon>'
      +   '</button>'

      +   '<div class="zimm-navigation-nav-links">'
      +     '<zimm-nav-item label="New"></zimm-nav-item>'
      +     '<zimm-nav-item label="Clothing"></zimm-nav-item>'
      +     '<zimm-nav-item label="Accessories"></zimm-nav-item>'
      +     '<zimm-nav-item label="Collections"></zimm-nav-item>'
      +     '<zimm-nav-item label="Z.Immerse"></zimm-nav-item>'
      +   '</div>'

      +   '<div class="zimm-navigation-right-active">'
      +     '<zimm-nav-item label="Close"></zimm-nav-item>'
      +     '<zimm-icon type="close" size="20" aria-hidden="true"></zimm-icon>'
      +   '</div>'

      +   '<div class="zimm-navigation-right-desktop">'
