      +       '<span class="zimm-navigation-search-trigger-label">Search</span>'
      +     '</div>'
      +     '<div class="zimm-navigation-icon-group">'
      +       '<zimm-icon type="profile" size="20" aria-label="Account"></zimm-icon>'
      +       '<zimm-icon type="wishlist" size="20" aria-label="Wishlist"></zimm-icon>'
      +       '<zimm-icon type="bag" size="20" aria-label="Bag"></zimm-icon>'
      +     '</div>'
      +   '</div>'

      +   '<div class="zimm-navigation-right-tablet">'
      +     '<div class="zimm-navigation-icon-group">'
      +       '<zimm-icon class="zimm-navigation-search-trigger" type="search" size="20" aria-label="Open search"></zimm-icon>'
      +       '<zimm-icon type="profile" size="20" aria-label="Account"></zimm-icon>'
      +       '<zimm-icon type="wishlist" size="20" aria-label="Wishlist"></zimm-icon>'
      +       '<zimm-icon type="bag" size="20" aria-label="Bag"></zimm-icon>'
      +     '</div>'
