      +   '<div class="zimm-navigation-right-mobile">'
      +     '<div class="zimm-navigation-icon-group">'
      +       '<zimm-icon class="zimm-navigation-search-trigger" type="search" size="20" aria-label="Open search"></zimm-icon>'
      +       '<zimm-icon type="bag" size="20" aria-label="Bag"></zimm-icon>'
      +     '</div>'
