9	/* ---- Name row: product name + wishlist toggle ---- */
10	
11	.zimm-product-detail-options-name-row {
12	  display: flex;
13	  align-items: flex-start;
14	  justify-content: space-between;
15	  gap: var(--zimm-scale-s);
16	  margin-bottom: var(--zimm-scale-xs);
17	}
