19	.zimm-product-detail-options-product-name {
20	  margin: 0;
21	  font-family: var(--zimm-font-family-body);
22	  /* TODO: --zimm-font-size-base and --zimm-font-lineheight-tight are not
23	     defined in the current token set (02-design/library/tokens/typography.css).
24	     This gap predates this port (present unresolved in the original
25	     Shadow-DOM component); carried over unchanged per conversion instructions
26	     rather than guessed at. Flag as a token candidate for design to confirm. */
27	  font-size: var(--zimm-font-size-base);
28	  font-weight: var(--zimm-font-weight-medium);
