/* Typography tokens + font loading
   Source: MCP-Test--Don-t-Use (Zimmermann Design System 2026)
   Split from common.css: 2026-07-25
   Managed by /extract, do not edit manually.
   --------------------------------------------------------- */

/* ---- Fonts ----
   Source Serif 4: Google Fonts (free).
   Futura Round: licensed. Files self-hosted in library/assets/Font Futura WOFF2/.
   NOTE (dev): these files must be served from a CDN in production.
   The Vercel deployment serves them automatically via the /library/:path* rewrite.
   For any other stack, upload the woff2 files to your CDN and update the src URLs below.
   FuturaRoundCond-* variants are present in assets but have no token mapping yet.
   --------------------------------------------------------- */
@import url('https://fonts.googleapis.com/css2?family=Source+Serif+4:ital,opsz,wght@0,8..60,400;0,8..60,500;1,8..60,400;1,8..60,500&display=swap');

@font-face {
  font-family: 'Futura Round';
  src: url('../assets/Font Futura WOFF2/FuturaRound-Regular.woff2') format('woff2');
  font-weight: 400;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Futura Round';
  src: url('../assets/Font Futura WOFF2/FuturaRound-Oblique.woff2') format('woff2');
  font-weight: 400;
  font-style: italic;
  font-display: swap;
}
@font-face {
  font-family: 'Futura Round';
  src: url('../assets/Font Futura WOFF2/FuturaRound-Light.woff2') format('woff2');
  font-weight: 300;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Futura Round';
  src: url('../assets/Font Futura WOFF2/FuturaRound-LightOblique.woff2') format('woff2');
  font-weight: 300;
  font-style: italic;
  font-display: swap;
}
@font-face {
  font-family: 'Futura Round';
  src: url('../assets/Font Futura WOFF2/FuturaRound-Medium.woff2') format('woff2');
  font-weight: 500;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Futura Round';
  src: url('../assets/Font Futura WOFF2/FuturaRound-MediumOblique.woff2') format('woff2');
  font-weight: 500;
  font-style: italic;
  font-display: swap;
}
@font-face {
  font-family: 'Futura Round';
  src: url('../assets/Font Futura WOFF2/FuturaRound-Demi.woff2') format('woff2');
  font-weight: 600;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Futura Round';
  src: url('../assets/Font Futura WOFF2/FuturaRound-DemiOblique.woff2') format('woff2');
  font-weight: 600;
  font-style: italic;
  font-display: swap;
}
@font-face {
  font-family: 'Futura Round';
  src: url('../assets/Font Futura WOFF2/FuturaRound-Bold.woff2') format('woff2');
  font-weight: 700;
  font-style: normal;
  font-display: swap;
}
@font-face {
  font-family: 'Futura Round';
  src: url('../assets/Font Futura WOFF2/FuturaRound-BoldOblique.woff2') format('woff2');
  font-weight: 700;
  font-style: italic;
  font-display: swap;
}

:root {

  /* ---- Typography: Font families ---- */
  --zimm-font-family-heading: 'Futura Round', sans-serif;
  --zimm-font-family-body:    'Futura Round', sans-serif;
  --zimm-font-family-serif:   'Source Serif 4', serif;

  /* ---- Typography: Font sizes ---- */
  --zimm-font-size-md:  24px;
  --zimm-font-size-xs:  16px;
  --zimm-font-size-2xs: 14px;
  --zimm-font-size-3xs: 12px;
  --zimm-font-size-4xs: 10px;

  /* ---- Typography: Line heights ---- */
  --zimm-font-lineheight-md:  32px;
  --zimm-font-lineheight-xs:  24px;
  --zimm-font-lineheight-2xs: 18px;
  --zimm-font-lineheight-3xs: 16px;
  --zimm-font-lineheight-4xs: 14px;

  /* ---- Typography: Letter spacing ---- */
  --zimm-font-letterspacing-sm: 0px;
  --zimm-font-letterspacing-xs:     -0.12px;
  --zimm-font-letterspacing-footer:  0.4px;

  /* ---- Typography: Font weights ---- */
  --zimm-font-weight-medium:  500;
  --zimm-font-weight-regular: 400;

}


/* ---- Typography classes ---- */

.zimm-text-h1-strong {
  font-family: var(--zimm-font-family-heading);
  font-weight: var(--zimm-font-weight-medium);
  font-size: var(--zimm-font-size-md);
  line-height: var(--zimm-font-lineheight-md);
  letter-spacing: var(--zimm-font-letterspacing-sm);
  text-transform: uppercase;
}

.zimm-text-h1 {
  font-family: var(--zimm-font-family-heading);
  font-weight: var(--zimm-font-weight-regular);
  font-size: var(--zimm-font-size-md);
  line-height: var(--zimm-font-lineheight-md);
  letter-spacing: var(--zimm-font-letterspacing-sm);
  text-transform: uppercase;
}

.zimm-text-h2-strong {
  font-family: var(--zimm-font-family-heading);
  font-weight: var(--zimm-font-weight-medium);
  font-size: var(--zimm-font-size-md);
  line-height: var(--zimm-font-lineheight-xs);
  letter-spacing: var(--zimm-font-letterspacing-sm);
}

.zimm-text-h3-strong {
  font-family: var(--zimm-font-family-heading);
  font-weight: var(--zimm-font-weight-medium);
  font-size: var(--zimm-font-size-xs);
  line-height: var(--zimm-font-lineheight-2xs);
  letter-spacing: var(--zimm-font-letterspacing-xs);
  text-transform: uppercase;
}

.zimm-text-label {
  font-family: var(--zimm-font-family-body);
  font-weight: var(--zimm-font-weight-medium);
  font-size: var(--zimm-font-size-xs);
  line-height: var(--zimm-font-lineheight-xs);
  letter-spacing: var(--zimm-font-letterspacing-sm);
}

.zimm-text-serif {
  font-family: var(--zimm-font-family-serif);
}

.zimm-text-caption {
  font-family: var(--zimm-font-family-body);
  font-weight: var(--zimm-font-weight-medium);
  font-size: var(--zimm-font-size-3xs);
  line-height: var(--zimm-font-lineheight-2xs);
  letter-spacing: var(--zimm-font-letterspacing-sm);
}

.zimm-text-link-lg {
  font-family: var(--zimm-font-family-body);
  font-weight: var(--zimm-font-weight-medium);
  font-size: var(--zimm-font-size-2xs);
  line-height: var(--zimm-font-lineheight-3xs);
  letter-spacing: -0.14px;
  text-transform: uppercase;
  text-decoration: underline;
  color: var(--zimm-color-link-default);
  text-decoration-color: currentColor;
  transition: color 0.15s ease;
}

a.zimm-text-link-lg:hover {
  color: var(--zimm-color-link-hover);
}

a.zimm-text-link-lg:focus-visible {
  outline: var(--zimm-border-width-default) solid var(--zimm-color-border-focus);
  outline-offset: 2px;
  color: var(--zimm-color-link-hover);
}

.zimm-text-link-sm {
  font-family: var(--zimm-font-family-body);
  font-weight: var(--zimm-font-weight-medium);
  font-size: var(--zimm-font-size-3xs);
  line-height: var(--zimm-font-lineheight-4xs);
  letter-spacing: var(--zimm-font-letterspacing-xs);
  text-transform: capitalize;
  text-decoration: underline;
}

.zimm-text-btn-lg {
  font-family: var(--zimm-font-family-body);
  font-weight: var(--zimm-font-weight-medium);
  font-size: var(--zimm-font-size-2xs);
  line-height: var(--zimm-font-lineheight-3xs);
  letter-spacing: var(--zimm-font-letterspacing-sm);
  text-transform: uppercase;
}

.zimm-text-btn-sm {
  font-family: var(--zimm-font-family-body);
  font-weight: var(--zimm-font-weight-medium);
  font-size: var(--zimm-font-size-3xs);
  line-height: var(--zimm-font-lineheight-2xs);
  letter-spacing: var(--zimm-font-letterspacing-sm);
  text-transform: uppercase;
}

.zimm-text-product-name {
  font-family: var(--zimm-font-family-body);
  font-weight: var(--zimm-font-weight-medium);
  font-size: var(--zimm-font-size-2xs);
  line-height: var(--zimm-font-lineheight-3xs);
  letter-spacing: var(--zimm-font-letterspacing-sm);
  text-transform: uppercase;
}

.zimm-text-nav {
  font-family: var(--zimm-font-family-body);
  font-weight: var(--zimm-font-weight-medium);
  font-size: var(--zimm-font-size-3xs);
  line-height: normal;
  letter-spacing: var(--zimm-font-letterspacing-sm);
  text-transform: uppercase;
}

.zimm-text-serif {
  font-family: var(--zimm-font-family-serif);
  font-weight: var(--zimm-font-weight-regular);
  font-style: italic;
  font-size: var(--zimm-font-size-3xs);
  line-height: var(--zimm-font-lineheight-3xs);
  letter-spacing: var(--zimm-font-letterspacing-sm);
}

.zimm-text-price {
  font-family: var(--zimm-font-family-body);
  font-weight: var(--zimm-font-weight-medium);
  font-size: var(--zimm-font-size-2xs);
  line-height: var(--zimm-font-lineheight-2xs);
  letter-spacing: var(--zimm-font-letterspacing-sm);
}

.zimm-text-footer {
  font-family: var(--zimm-font-family-body);
  font-weight: var(--zimm-font-weight-medium);
  font-size: var(--zimm-font-size-4xs);
  line-height: var(--zimm-font-lineheight-4xs);
  letter-spacing: var(--zimm-font-letterspacing-footer);
  text-transform: uppercase;
}

.zimm-text-body1-strong {
  font-family: var(--zimm-font-family-body);
